def window():
    w = json.loads((HERE / "window-60.json").read_text())["window"]
    if not w.get("applies"):
        return None
    f = lambda s: datetime.fromisoformat(s.replace("Z", "+00:00"))
    return f(w["from_utc"]), f(w["to_utc"])


def in_window(t=None):
    t = t or datetime.now(timezone.utc)
    w = window()
    return bool(w) and w[0] <= t <= w[1]


def job1_too_late(t=None):
    """k60-rule.md: job 1 is not submitted later than 2 hours before the window opens."""
    t = t or datetime.now(timezone.utc)
    w = window()
    return bool(w) and t > w[0] - JOB1_LEAD and t < w[1]


# --------------------------------------------------------------------------- the calibration record
def record_stamp(backend, kind, job_status="", refresh=True):
    """Read the backend's properties, save the snapshot if its stamp is new, compare it by value with the previous one
    (history 01's compare and other_changes), and append a row to stamps-60.csv."""
    STAMPS.mkdir(exist_ok=True)
    p = backend.properties(refresh=refresh)
    s = p.last_update_date.astimezone(timezone.utc)
    name = f"snapshot-{s.strftime('%Y%m%dT%H%M%SZ')}.json"
    path = STAMPS / name
    rows_p = HERE / "stamps-60.csv"
    rows = list(csv.DictReader(rows_p.open())) if rows_p.exists() else []
    seen = [r["snapshot"] for r in rows]
    new = name not in seen
    row = {"utc": now(), "kind": kind, "stamp_utc": s.strftime("%Y-%m-%dT%H:%M:%SZ"), "stamp_raw": str(p.last_update_date),
           "new_stamp": new, "job_status": job_status, "snapshot": name}
    if not path.exists():
        path.write_text(json.dumps(p.to_dict(), default=str, indent=1) + "\n")
    if new and seen:
        prev = STAMPS / seen[-1]
        c = TH.compare(TH.load(prev), TH.load(path))
        o = TH.other_changes(prev, path)
        row.update({"q_T1": c["q_T1"], "q_T2": c["q_T2"], "q_readout_error": c["q_readout_error"], "g1_any": c["g1_any"],
                    "cz_error": c["cz_error"], "cz_length": c["cz_length"], "other_values_changed": o["other_values_changed"],
                    "any_value_changed": o["any_value_changed"]})
    row.update(chain_readout(p))
    with rows_p.open("a", newline="") as fh:
        w = csv.DictWriter(fh, fieldnames=STAMP_FIELDS)
        if not rows:
            w.writeheader()
        w.writerow(row)
    return row


def chain_readout(p):
    """The chains' published readout error at this read, and each M's published P(1|0) and P(0|1) (k60-rule.md: the
    calibration record carries the chains' published readout at every stamp read). Empty before the draw."""
    cp = HERE / "chains-60.json"
    if not cp.exists():
        return {}
    chains = [d["chain"] for d in json.loads(cp.read_text())["drawn"]]

    def qp(q, name):
        try:
            v = p.qubit_property(q).get(name, (None,))[0]
            return None if v is None else round(float(v), 5)
        except Exception:
            return None

    return {"chain_readout_error": json.dumps({str(q): qp(q, "readout_error") for c in chains for q in c}),
            "M_prob_meas1_prep0": json.dumps({str(c[1]): qp(c[1], "prob_meas1_prep0") for c in chains}),
            "M_prob_meas0_prep1": json.dumps({str(c[1]): qp(c[1], "prob_meas0_prep1") for c in chains})}


def cycle_check(row, t=None):
    """k60-rule.md: neither job is submitted while the day's cycle is in progress, from a stamp at which T1 changed on
    more than half the qubits until 30 minutes after the next stamp at which CZ errors changed on more than half the
    edges. From window-60.json: the latest T1 and CZ stamps of the 48-hour walk. Then the snapshot just read (row, from
    record_stamp) is compared by value with the walk's snapshot of that CZ stamp (history 01's compare): if T1 has since
    changed on more than half the qubits, or CZ errors on more than half the edges, a new cycle has begun since the
    walk, and the check does not pass (the runner stops and reports)."""
    t = t or datetime.now(timezone.utc)
    cyc = json.loads((HERE / "window-60.json").read_text())["cycle"]
    out = {"utc": now(), "latest_T1_stamp_utc": cyc["latest_T1_stamp_utc"], "latest_CZ_stamp_utc": cyc["latest_CZ_stamp_utc"],
           "cycle_complete_in_48h": cyc["cycle_complete_in_48h"], "submissions_from_utc": cyc["submissions_from_utc"], "snapshot_read": row["snapshot"]}
    if not cyc["cycle_complete_in_48h"]:
        return {**out, "pass": False, "reason": "the walk's latest T1 stamp has no CZ stamp after it"}
    f = lambda s: datetime.fromisoformat(s.replace("Z", "+00:00"))
    if t < f(cyc["submissions_from_utc"]):
        return {**out, "pass": False, "reason": "less than 30 minutes after the latest CZ stamp"}
    cz_snap = HERE / "history-60" / "snapshots" / f"snapshot-{f(cyc['latest_CZ_stamp_utc']).strftime('%Y%m%dT%H%M%SZ')}.json"
    c = TH.compare(TH.load(cz_snap), TH.load(STAMPS / row["snapshot"]))
    since = {"q_T1": c["q_T1"], "cz_error": c["cz_error"], "n_edges": c["n_edges"]}
    new_cycle = c["q_T1"] > TH.N_QUBITS / 2 or c["cz_error"] > c["n_edges"] / 2
    return {**out, "changed_since_latest_CZ_stamp": since, "new_cycle_since_walk": new_cycle, "pass": not new_cycle,
            "reason": "a new T1 or CZ step since the walk's latest CZ stamp" if new_cycle else "the day's cycle is complete and no new step has come"}


# --------------------------------------------------------------------------- the draw
def draw_chains(backend):
    """k60-rule.md's procedure, exactly. Returns the record for chains-60.json."""
    t, props = backend.target, backend.properties()
    cz = {tuple(int(x) for x in k) for k in t["cz"].keys() if k is not None}
    adj = defaultdict(set)
    for a, b in cz:
        adj[a].add(b)
        adj[b].add(a)
    cmap = {tuple(e) for e in backend.coupling_map.get_edges()}
    cands = [(l1, m, l3) for m in sorted(adj) for l1 in sorted(adj[m]) for l3 in sorted(adj[m]) if l1 != l3]

    def safe(fn, *a):
        try:
            v = fn(*a)
            return None if v is None else float(v)
        except Exception:
            return None

    def ro(q):
        return safe(props.readout_error, q)

    def edge_err(a, b):
        errs = [safe(props.gate_error, "cz", [x, y]) for x, y in ((a, b), (b, a)) if (x, y) in cz]
        return None if (not errs or any(e is None for e in errs)) else max(errs)

    def operational(q):
        try:
            return bool(props.is_qubit_operational(q))
        except Exception:
            return False

    reasons = defaultdict(int)
    keep = []
    for ch in cands:
        l1, m, l3 = ch
        if set(ch) & USED:
            reasons["uses a qubit of Kickoffs 47 to 54 on ibm_fez"] += 1
            continue
        if not all(operational(q) for q in ch):
            reasons["a qubit not operational"] += 1
            continue
        r = [ro(q) for q in ch]
        if any(x is None for x in r):
            reasons["a readout error missing"] += 1
            continue
        if max(r) > RO_MAX:
            reasons["a readout error above 3%"] += 1
            continue
        e = [edge_err(l1, m), edge_err(m, l3)]
        if any(x is None for x in e):
            reasons["a CZ error missing"] += 1
            continue
        if max(e) > CZ_MAX:
            reasons["a CZ error above 1%"] += 1
            continue
        keep.append(ch)
    keep.sort(key=lambda c: (c[1], c[0], c[2]))
    shuffled = [list(c) for c in keep]
    np.random.default_rng(DRAW_SEED).shuffle(shuffled)
    taken, used = [], set()
    for c in shuffled:
        if set(c) & used:
            continue
        taken.append(c)
        used |= set(c)
        if len(taken) == N_CHAINS:
            break

    def info(c):
        l1, m, l3 = c
        return {"chain": c, "M": m, "readout_error": {str(q): ro(q) for q in c},
                "cz_error": {f"{l1}-{m}": edge_err(l1, m), f"{m}-{l3}": edge_err(m, l3)},
                "T1_us": {str(q): (safe(props.t1, q) or 0) * 1e6 for q in c}, "T2_us": {str(q): (safe(props.t2, q) or 0) * 1e6 for q in c},
                "operational": {str(q): operational(q) for q in c}}

    return {"procedure": "k60-rule.md: candidates on the live target's CZ edges (either direction), L1 != L3; exclusions (a qubit used on ibm_fez in Kickoffs 47 to 54; operational; readout error above 3%; CZ error above 1%, the larger of the edge's listed directions; a missing value excludes); sort by (M, L1, L3); numpy.random.default_rng(6060).shuffle; take in order, skipping any chain that shares a qubit with one taken, until four",
            "backend": backend.name, "calibration_stamp": str(props.last_update_date), "utc": now(), "excluded_qubits": sorted(USED),
            "cz_edges_directed": len(cz), "coupling_map_edges_directed": len(cmap), "coupling_map_equals_cz_edges": cmap == cz,
            "n_candidates": len(cands), "n_excluded": dict(reasons), "n_survivors": len(keep),
            "shuffled_first_20": shuffled[:20], "drawn": [info(c) for c in taken], "enough": len(taken) == N_CHAINS}


# --------------------------------------------------------------------------- the circuits
def made(qc, chain, backend, name):
    ins, isa = K51._made(qc, chain, backend)
    return K50.rebuild(isa, ins, name)


def base(chain, backend):
    t, dt = backend.target, backend.dt
    no0 = W.build_wait_test(chain, False, backend)
    tl0 = K50.timed(K50.schedule(no0, backend, chain)[0], t, dt, chain)
    return no0, {"T_M": K50.window(tl0, chain[1]), "tl_no": tl0, "T": K50.window(tl0, chain[1])["T_dt"]}


def build_job1_chain(chain, backend):
    no0, info = base(chain, backend)
    c = {("R1", "sweep", phi): W.build_wait_ramsey(chain, backend, phase=math.radians(phi)) for phi in PHIS1}
    return c, info, no0


def build_job2_chain(chain, backend, phi_star):
    no0, info = base(chain, backend)
    M = chain[1]
    c = {}
    for k, role, _ in JOB2:
        phi = {"peak": phi_star, "plus90": 90}.get(role, 0)
        if k == "W-no":
            c[(k, role, phi)] = W.build_wait_test(chain, False, backend, phase=math.radians(phi))
        elif k == "R1":
            c[(k, role, phi)] = W.build_wait_ramsey(chain, backend, phase=math.radians(phi))
        elif k == "R0":
            c[(k, role, phi)] = W.build_wait_ramsey(chain, backend, neighbours="idle", phase=math.radians(phi))
        elif k == "W-ref":
            c[(k, role, phi)] = W.build_wait_test(chain, True, backend)
        elif k == "Z":
            c[(k, role, phi)] = made(K50.logical("Z", info["T"]), chain, backend, f"Z-{M}")
        elif k in READOUT:
            c[(k, role, phi)] = readout_circuit(k, M, backend)
    return c, info, no0


def readout_circuit(k, M, backend):
    """The two readout circuits on M alone, outside the package: P10 measures with no gate (P(1|0)); P01 applies X,
    then measures (P(0|1)). One qubit, one clbit; translated by manacitra.wait.to_backend on [M], as the idle Ramsey."""
    from qiskit import QuantumCircuit
    qc = QuantumCircuit(1, 1, name=f"{k}-{M}")
    if k == "P01":
        qc.x(0)
    qc.measure(0, 0)
    return made(qc, [M], backend, f"{k}-{M}")


def m_clbit_of(k):
    return 0 if k in ("R0", *READOUT) else M_CLBIT


def checks(chain, circ, info, no0, backend, job):
    """Section 1's checks on one chain's circuits. circ is keyed (circuit, role, phi)."""
    t, dt = backend.target, backend.dt
    L1, M, L3 = chain
    ideal = W.wait_test_ideal()
    T = info["T"]
    rec, tls = {}, {}
    # check 1 on the wait test (in job 1 it is built for the checks only, not submitted)
    ops0 = {a: int(b) for a, b in no0.count_ops().items()}
    rec["W-no unedited (checks)"] = {"count_ops": ops0, "structure_5cz_6meas_3reset": ops0.get("cz") == 5 and ops0.get("measure") == 6 and ops0.get("reset") == 3,
                                     "no_swap": ops0.get("swap", 0) == 0, "layout_as_drawn": list(no0.layout.initial_index_layout(filter_ancillas=True)) == chain,
                                     "both_couplers_used": {tuple(sorted(no0.find_bit(q).index for q in i.qubits)) for i in no0.data if i.operation.name == "cz"} == {tuple(sorted((L1, M))), tuple(sorted((M, L3)))},
                                     "exact_F": W.fidelity(W.exact_distribution(no0), ideal)}
    rec["W-no unedited (checks)"]["exact_F_is_1"] = abs(rec["W-no unedited (checks)"]["exact_F"] - 1) < 1e-6
    exact = {}
    for (k, role, phi), c in circ.items():
        lay = [M] if k in ("R0", *READOUT) else chain
        ins, _ = K50.schedule(c, backend, lay)
        tl = K50.timed(ins, t, dt, lay)
        tls[(k, role, phi)] = tl
        ops = {a: int(b) for a, b in c.count_ops().items()}
        init = list(c.layout.initial_index_layout(filter_ancillas=True))
        p = W.exact_distribution(c)
        bit = lambda key, i: key[::-1][i] == "1"
        r = {"phi_deg": phi, "count_ops": ops, "no_swap": ops.get("swap", 0) == 0, "layout_as_drawn": init == lay,
             "non_delay_ops_only_on_chain": {c.find_bit(q).index for i in c.data if i.operation.name != "delay" for q in i.qubits} <= set(lay)}
        seq = K51.m_sequence(c, M)
        names = [n for n, _ in seq]
        if k.startswith("W"):
            r["exact_F"] = W.fidelity(p, ideal)
            r["exact_F_expected"] = math.cos(math.radians(phi) / 2) ** 2
            r["exact_F_as_expected"] = abs(r["exact_F"] - r["exact_F_expected"]) < 1e-6
            r["structure_5cz_6meas_3reset"] = ops.get("cz") == 5 and ops.get("measure") == 6 and ops.get("reset") == 3
            r["both_couplers_used"] = {tuple(sorted(c.find_bit(q).index for q in i.qubits)) for i in c.data if i.operation.name == "cz"} == {tuple(sorted((L1, M))), tuple(sorted((M, L3)))}
            if k == "W-ref":
                r["pulses_on_M"] = K50.x_on(c, M) > K50.x_on(no0, M)
        elif k in READOUT:
            r["exact_P1_M"] = sum(v for key, v in p.items() if bit(key, 0))
            r["exact_P1_expected"] = 1.0 if k == "P01" else 0.0
            r["exact_P1_as_expected"] = abs(r["exact_P1_M"] - r["exact_P1_expected"]) < 1e-9
            r["one_measure_one_clbit"] = ops.get("measure") == 1 and c.num_clbits == 1
            gates = [n for n, _ in seq if n not in ("measure", "barrier")]
            r["M_ops_before_measure"] = gates
            r["gates_as_named"] = (gates == ["x"]) if k == "P01" else (gates == [])
            exact[(k, role, phi)] = r["exact_P1_M"]
        else:
            mb = m_clbit_of(k)
            r["exact_P1_M"] = sum(v for key, v in p.items() if bit(key, mb))
            r["exact_P1_expected"] = 0.0 if k == "Z" else math.sin(math.radians(phi) / 2) ** 2
            r["exact_P1_as_expected"] = abs(r["exact_P1_M"] - r["exact_P1_expected"]) < 1e-9
            exact[(k, role, phi)] = r["exact_P1_M"]
            w = K50.window(tl, M)
            r["M_window"] = w
            if k == "Z":
                r["window_ok"] = w["T_dt"] == 0
            elif k == "R0":
                r["window_ok"] = w["T_dt"] == W.even_wait(T, getattr(t, "granularity", 1) or 1)
                r["window_beside_T_M"] = {"idle_even_T_M_dt": w["T_dt"], "T_M_dt": T}
            else:
                r["window_ok"] = w["T_dt"] == T
        if k in ("W-no", "R0", "R1"):
            i = names.index("sx")
            r["M_first_H_then_next"] = seq[i - 1:i + 3]
            if phi:
                r["phase_one_rz_after_first_H"] = (seq[i - 1] == ("rz", 90.0) and seq[i + 1] == ("rz", 90.0) and seq[i + 2][0] == "rz"
                                                   and abs(seq[i + 2][1] - float(phi)) < 1e-6 and names.count("rz") == 5)
            else:
                r["phase_none_at_0"] = names.count("rz") == 4
        if k == "W-no":
            j0, j1 = names.index("sx"), len(names) - 1 - names[::-1].index("sx")
            between = names[j0 + 1:j1]
            core = between[1:-1]
            if phi:
                core = core[1:] if core[:1] == ["rz"] else ["?"]
            r["M_ops_between_H"] = between
            r["check_cz_barrier_and_phase_only"] = set(core) <= {"cz", "barrier"} and core.count("cz") == 5
        rec[f"{k}|{role}|{phi}"] = r
    tab = {str(q): {"W-no unedited": K50.events(info["tl_no"], q),
                    **{f"{k}|{role}|{phi}": K50.events(tl, q) for (k, role, phi), tl in tls.items() if k in ("R1", "W-no")}} for q in (L1, L3)}
    same = all(v == tab[str(q)]["W-no unedited"] for q in (L1, L3) for v in tab[str(q)].values())
    rec["_neighbours"] = {"measure_reset_times": tab, "R1_and_W_no_same_as_W_no_unedited": same}
    good_fit = True
    if job == 1:
        y = np.array([exact[("R1", "sweep", p)] for p in PHIS1])
        th = float(A52.theta_R(y))
        rec["_exact_fit"] = {"theta_R1_deg": th, "phi_star_deg": A57.peak_phase(th), "pass": abs(th) < 1e-6 and A57.peak_phase(th) == 180}
        good_fit = rec["_exact_fit"]["pass"]
    flat = [v for kk, r in rec.items() if not kk.startswith("_") for v in r.values() if isinstance(v, bool)]
    return rec, all(flat) and same and good_fit


def build(backend, chains, job, phis=None):
    circ, recs, infos, ok = {}, {}, {}, True
    for chain in chains:
        n = str(chain[1])
        if job == 1:
            c, info, no0 = build_job1_chain(chain, backend)
        else:
            c, info, no0 = build_job2_chain(chain, backend, phis[n])
        r, good = checks(chain, c, info, no0, backend, job)
        ok = ok and good
        circ[n], recs[n], infos[n] = c, r, {"T_M": info["T_M"], "chain": chain}
    return circ, recs, infos, ok


def assemble(circ, chains, job):
    items = [(str(ch[1]), ch, k, cp) for ch in chains for k in circ[str(ch[1])] for cp in range(1, COPIES + 1)]
    perm = np.random.default_rng(SEEDS[f"order_job{job}"]).permutation(len(items))
    block_of = {(k, role): b for k, role, b in JOB2}
    circs, labels, shots = [], [], []
    for i in perm:
        n, chain, (k, role, phi), cp = items[i]
        block = "sweep" if job == 1 else block_of[(k, role)]
        part = "S" if job == 1 else ("W" if k.startswith("W") else "R")
        labels.append({"job": job, "M": int(n), "chain": chain, "circuit": k, "role": role, "phi_deg": phi, "copy": cp, "m_clbit": m_clbit_of(k),
                       "part": part, "block": block, "built_by": "outside the package (hw_50 Z)" if k == "Z" else "package"})
        circs.append(circ[n][(k, role, phi)])
        shots.append(SHOTS[block])
    return circs, labels, shots
